import json,pathlib
items=[]
def add(id,title,pages,summary,steps=[],counts=[],refs=[],notes=[],topic='method'):
 items.append(dict(id=id,title=title,pages=pages,summary=summary,steps=steps,counts=counts,refs=refs,notes=notes,topic=topic,chapter='method' if topic=='method' else 'c1'))
def op(label,nums,result,kind='subtract',unit='yıl'):
 return dict(label=label,operands=nums,expected=result,operator=kind,unit=unit)
def count(s,kind,value,label='',letters=None,start=None,end=None):
 d=dict(surah=s,kind=kind,claimed=value,label=label)
 if letters:d['letters']=letters
 if start:d.update(start=start,end=end)
 return d
add('yontem','Sayılardan tarih çıkarma yöntemi',[9,10,18], 'Yazar, ayet, kelime veya harf sayısını ve bazen bir sözcüğün metindeki sıra numarasını güneş yılıyla eşleştirir. Hangi birimin kullanılacağı her olay için ayrı seçilir. Sure adı da hangi kişi veya olayla bağlantı kurulacağına rehber kabul edilir.',notes=['Bir metin biriminin bir güneş yılına eşit sayılması, kitabın varsayımıdır; aritmetik işlemin kendisinden çıkmaz.','Yazar 18. sayfada bu yaş hesaplama yönteminin genel bir kural olmadığını açıkça söyler.','Osmanî yazım kullanıldığını belirtir; fakat tüm hesaplar için tek bir ayrıntılı kelime ayırma, hareke ve harf normalleştirme şartnamesi vermez.'])
add('sinirlar','Yazarın kendi sınırlılık açıklamaları',[10,11,12,28], 'Yazar bütün sonuçların yüzde yüz doğru olduğunu ileri sürmediğini, rastlantı olasılığının payı bulunduğunu ve bazı tarihleri ya da başlangıç harflerini açıklayamadığını belirtir. İncelemesini tamamen bitirmeden yayımladığını, başkalarının hatalarını düzeltebileceğini söyler. Hûd için önerdiği tarihlerin doğruluğunu kesin olarak ileri süremediğini 28. sayfada ayrıca ifade eder.',notes=['Bu menü kitabın savlarını Türkçe olarak aktarır; tarihsel gerçeklik veya dinî kesinlik sertifikası vermez.','Hesabın aritmetik olarak tutması, kullanılan sayımın, tarihlerin veya sayılar arasındaki ilişkinin doğrulandığı anlamına gelmez.'])
add('giris-firavun','Firavun için 54 ve 18 eşleştirmeleri',[9], 'Girişte yazar, ek almamış “Firavun” sözcüğünün 54 kez geçmesini III. Thutmose için kabul ettiği 54 yıllık saltanatla; “Firavun halkı” ifadesinin 18 kez geçmesini ise 18. Hanedan ile ilişkilendirir.',notes=['Bunlar yazarın sayım ve tarih eşleştirmeleridir. “Ek almamış” sözcük ve ifade sınırlarının tüm metinde nasıl uygulandığı ayrıca denetlenmelidir.','Ayrıntılı ele alış IV. bölümdedir; bu kayıt yalnızca girişte verilen savı kapsar.'])
add('giris-kehf','Kehf kıssasında 308 sözcük ve 309. konum',[10], 'Yazar, Bassam Jarrar’a atıfla mağara kıssasının başlangıcından “üç yüz ve dokuz arttırdılar” ifadesine kadar 308 kelime bulunduğunu, söz konusu ifadenin sıra numarasının 309 olduğunu aktarır.',[op('Önceki 308 birimden sonraki sıra', [308,1],309,'add','sıra')],refs=[[18,25]],notes=['Başlangıç noktası, dahil etme/dışlama kuralı ve “ifadenin sıra numarası”nın kelime düzeyinde tanımı girişte tam açıklanmaz. Bu nedenle 308 sayımı bu kayıtta yeniden doğrulanmış sayılmaz.','Bu savın ayrıntıları V. bölümde ele alınmaktadır.'])
add('giris-misir','Mısır kronolojisinde 480, 430 ve 330 yıl',[12], 'Yazar, Kitâb-ı Mukaddes kaynaklı 480 yıllık tapınak–çıkış aralığını, 430 yıllık Mısır’da kalış anlatısını ve bunların farklı firavunlarla ilişkilendirilmesini tartışır. Kendi modelinde Mısır’da kalışın 330 yıl olduğunu ileri sürer.',notes=['Bu sayfa 330 sonucunu üreten tam işlem zincirini vermez. Rakamlar kaynakta tartışıldığı biçimde aktarılır; bağımsız tarihsel doğrulama yapılmış değildir.'])
add('giris-takvim','Milat, yıl sıfırı ve bir yıllık tarih farkları',[12], 'Yazar İsa’nın doğumunu MÖ 1 olarak kabul eder ve bunu “sıfır yıl” diye yorumlar. İskender’in ölümü için 323 yerine MÖ 322, Muhammed’in doğumu için MS 572 tarihini savunur.',notes=['Standart MÖ/MS tarihlemelerinde yıl sıfırı yoktur; astronomik yıl numaralandırması farklıdır. İki düzen karıştırılmamalıdır.','Kaynak, Muhammed’in yaygın doğum tarihi ifadesini bu sayfada “571 BC” biçiminde basmıştır. Bu, metindeki MÖ/MS tutarsızlığı olarak kaydedilir; sessizce düzeltilmiş bir alıntı değildir.'])
add('giris-dort-esik','Girişteki dört kelime sayısı–tarih eşleştirmesi',[13], 'Yazar Nahl’in 1844 kelimesini İbrahim’in MÖ 1844 ölümüyle; Yûsuf’un 1777 kelimesini Yusuf’un MÖ 1777 doğumuyla; Meryem’in 961 kelimesini Davud’un MÖ 961 ölümüyle; Kasas’ın 1430 kelimesini Musa’nın firavununun ölümü ve çıkış için önerdiği MÖ 1430 ile eşleştirir.',counts=[count(16,'words',1844,'Nahl'),count(12,'words',1777,'Yûsuf'),count(19,'words',961,'Meryem'),count(28,'words',1430,'Kasas')],notes=['Bunlar girişte belirtilen dayanak örnekleridir; ilgili kişi ve olayların ayrıntılı hesapları sonraki bölümlerde ayrıca incelenecektir.'])
add('adem-bakara','Âdem–Musa aralığı ve Bakara’nın 6117 kelimesi',[15,16], 'Yazar Âdem’in yaratılışını MÖ 7610, Musa’nın doğumunu MÖ 1493 alır. İki tarih arasındaki 6117 yılı Bakara suresi için verdiği 6117 kelime sayısıyla eşleştirir. Surede İbrahim adının 15, Musa adının 13 kez geçtiğini de seçim gerekçesi bağlamında belirtir.',[op('Kitapta kabul edilen iki tarih arasındaki fark',[7610,1493],6117)],counts=[count(2,'words',6117)],notes=['Âdem ve Musa için kullanılan mutlak tarihler yazarın modeline aittir.','Sure adı, konu ve kişi adlarının tekrarları hangi tarihin seçileceğine gerekçe yapılır; bu seçim tek başına bağımsız tarih kanıtı değildir.'],topic='adam')
add('adem-alti-aralik','Altı zaman aralığının 6117 toplamı',[15,16], 'Musa’nın doğumundan İbrahim’in ölümüne 351; buradan Hûd’un doğumuna 1917; Hûd’un doğumundan tufana 1673; tufandan Nuh’un doğumuna 950; Nuh’un doğumundan Âdem’in ölümüne 226; Âdem’in yaşamı için 1000 yıl seçilir. Yazar bu altı parçanın toplamını Bakara kelime sayısıyla eşleştirir.',[op('Altı seçilmiş aralığın toplamı',[351,1917,1673,950,226,1000],6117,'add')],counts=[count(55,'words',351),count(11,'words',1917),count(11,'letters',1673,'Hûd 25–49',start=25,end=49),count(71,'words',226)],refs=[[29,14],[11,25],[11,49]],notes=['Aynı zincirde kelime sayısı, harf sayısı, ayette belirtilen süre ve rivayete dayalı yaş birlikte kullanılır.','950 yılın doğumdan tufana kadar geçen yaş olarak alınması ayrıca bir yorumdur.'],topic='adam')
add('adem-1000','Âdem’in anıldığı ayetlerde 1000 harf tablosu',[17,18], 'Kitap, “Âdemoğulları” ifadelerini dışarıda bırakarak Âdem’in anıldığı 16 ayetin harf sayılarını verir. Tablo toplamı 1000’dir; yazar bu sayıyı 1000 yıllık ömür olarak yorumlar. Kitâb-ı Mukaddes’teki 930 yıl ile karşılaştırır.',notes=['Aşağıdaki tablo kitaptaki sayıları aynen sayısal veri olarak taşır. Toplamın doğruluğu, sayım kurallarının veya yaş yorumunun doğruluğundan ayrıdır.','Yazar, Âdem’in yaşı için bir hadis anlatısını da dayanak olarak kullanır; bu menü hadis sıhhat değerlendirmesi yapmaz.'],topic='adam')
