add('adem-olum','Âdem’in ölümünün MÖ 6610’a yerleştirilmesi',[14,16,17], 'Yazarın MÖ 7610 yaratılış tarihi ve 1000 yıllık ömür kabulü, birinci kronoloji tablosundaki MÖ 6610 ölüm tarihine karşılık gelir.',[op('Tablodaki tarihin açık aritmetik yazımı',[7610,1000],6610)],notes=['Bu işlem kronoloji ile ömür kabulünün açık yazımıdır; bu biçimiyle ayrı bir eşitlik olarak basılı değildir.'],topic='adam')
add('nuh-dogum','Nuh’un doğumu: Âdem’den 226 yıl sonra',[18], 'Nûh suresi için verilen 226 kelime, Âdem’in ölümü ile Nuh’un doğumu arasındaki yıl sayısı kabul edilir. Kitap, Kitâb-ı Mukaddes’teki 126 ile son iki rakamın ortak olmasına da dikkat çeker.',[op('Âdem’in ölümü ile Nuh’un doğumu',[6610,6384],226)],counts=[count(71,'words',226)],notes=['126 ve 226’nın “26” sonunu paylaşması, kendi başına hangi sayının tarihsel olarak doğru olduğunu belirlemez.'],topic='noah')
add('lamek-dogum','Lâmek’in doğumu için 182 yıl',[18,19], 'Yazar, Nuh’un babası Lâmek’in Nuh’tan 182 yıl önce doğduğu bilgisini Kitâb-ı Mukaddes’ten alır. Nuh için kabul ettiği MÖ 6384’e bu süreyi ekleyerek MÖ 6566’ya ulaşır.',[op('Nuh’un doğumuna önceki 182 yılın eklenmesi',[6384,182],6566,'add')],notes=['182, Kur’an harf/kelime sayımından değil başka bir dinî kaynaktan alınır.'],topic='noah')
add('lamek-1044','A‘râf’taki Âdem anlatısı ve 1044 yıl',[19], 'Âdem’in yaratılışı ile Lâmek’in doğumu arasında 1044 yıl hesaplanır. Yazar bunu A‘râf suresindeki Âdem anlatısının 1044 harfiyle eşleştirir.',[op('İki kabul edilmiş tarih arasındaki fark',[7610,6566],1044)],notes=['Bu sayfada kıssanın kesin başlangıç ve bitiş ayetleri verilmez; bu yüzden kapsam otomatik olarak tahmin edilmemiştir.'],topic='noah')
add('tufan-950','Tufanın MÖ 5434’e yerleştirilmesi',[19], 'Ankebût 14’teki “bin yıldan elli yıl eksik” süre 950 olarak alınır. Yazar bunu Nuh’un doğumu ile tufan arasındaki toplam yaş kabul ederek MÖ 6384’ten çıkarır.',[op('Ayette belirtilen sürenin aritmetiği',[1000,50],950),op('Yazarın yaş yorumu ile tarih hesabı',[6384,950],5434)],refs=[[29,14]],notes=['Ayette anlatılan halkının arasındaki süre ile doğumdan itibaren toplam yaşın aynı sayılması yazarın yorumudur.','Kitap, Kitâb-ı Mukaddes’teki 600 yaş anlatısını da karşılaştırma amacıyla belirtir.'],topic='noah')
add('tufan-tarih-karsilastirma','Tufan için kitapta karşılaştırılan diğer tarihler',[19,20], 'Yazar, 1997 tarihli Ryan–Pitman çalışmasına atıfla yaklaşık MÖ 5500 ve 100 metreden fazla seviye farkı anlatır. Başka bir çalışma için MÖ 7500 tarihini, Kitâb-ı Mukaddes yorumları için MÖ 2282 ve MÖ 3568 tarihlerini aktarır. Bunları kendi MÖ 5434 önerisiyle tartışır.',notes=['Bu kayıt, kitabın aktardığı tarih ve ölçüleri listeler; jeoloji çalışmalarının bulgularını bağımsız olarak doğruladığı anlamına gelmez.','Yazar Karadeniz açıklamasının tartışmalı olduğunu kendisi de belirtir.'],topic='noah')
add('tufan-nisa','Tufan–Efrayim aralığı ve 3747 kelime',[20], 'Nisâ suresinin 3747 kelime olduğu savı, tufan için MÖ 5434 ile Efrayim’in ölümü için MÖ 1687 arasındaki farka bağlanır.',[op('Önerilen tarihler arasındaki fark',[5434,1687],3747)],counts=[count(4,'words',3747)],topic='noah')
add('tufan-lam','Bakara’daki 3198 lâm ve Eber bağlantısı',[20], 'Bakara’daki lâm harfinin 3198 tekrarı, tufan ile Eber’in ölümü arasındaki 3198 yıl olarak yorumlanır.',[op('Tufan ile Eber’in ölümü',[5434,2236],3198)],counts=[count(2,'occurrences',3198,'Lâm tekrarı',['ل'])],topic='noah')
add('nuh-1824','Nuh’un anıldığı ayetlerde 1824 harf tablosu',[20,21], 'Kitap, Nuh’un kavmi ve eşinin anıldığı ayetleri dışarıda bırakan 28 ayetlik bir harf tablosu verir. Toplam 1824 harf, Nuh’un ömrü olarak yorumlanır.',notes=['Tabloya dahil etme/dışlama kuralı, sayı ile yaş arasında ilişki kurma varsayımından ayrı incelenmelidir.','Aritmetik toplam aşağıdaki satırlardan yeniden hesaplanabilir.'],topic='noah')
