add('nuh-suresi','Nûh suresinde 28 ayet, 226 kelime ve 953 harf',[21,22], 'Yazar Nûh suresi için 28 ayet, 226 kelime ve 953 harf verir. 28 ayeti, önceki tabloda seçtiği 28 ayetle eşleştirir; 226 kelimeyi Âdem’in ölümü–Nuh’un doğumu aralığına yeniden bağlar. Uzun surelerin harf sayılarının kendi kabul ettiği yaklaşık 9625 yıllık insanlık tarihini aşabildiğini ve bunlar için henüz açıklama bulamadığını belirtir.',counts=[count(71,'verses',28),count(71,'words',226),count(71,'letters',953)],notes=['“Yaklaşık 9625 yıl” kitabın kronoloji çerçevesidir; burada insanlık tarihine ilişkin bilimsel bir sonuç olarak sunulmaz.'],topic='noah')
add('nuh-olum','Nuh’un ölümünün MÖ 4560’a yerleştirilmesi',[14,20,21,22], 'Nuh için kabul edilen MÖ 6384 doğum ile 1824 yıllık ömür, kronoloji tablosundaki MÖ 4560 ölüm tarihini verir.',[op('Kronoloji ve yaş kabulünün açık aritmetiği',[6384,1824],4560)],notes=['Bu yazım, tablolar arasındaki hesabı açıklaştırmak için verilmiştir; basılı metindeki ayrı bir eşitliğin birebir aktarımı değildir.'],topic='noah')
add('nuh-enam','En‘âm’ın 3050 kelimesi ve Âdem–Nuh aralığı',[22], 'En‘âm suresi için ileri sürülen 3050 kelime, Âdem’in yaratılışından Nuh’un ölümüne kadar olan 3050 yıla bağlanır.',[op('Yaratılış tarihi ile Nuh’un ölümü',[7610,4560],3050)],counts=[count(6,'words',3050)],topic='noah')
add('nuh-uzeyir','Bakara’daki 4214 elif ve Üzeyir’in ikinci ölümü',[22], 'Bakara’da elifin 4214 defa geçtiği sayımı, Nuh’un ölümü ile yazarın Üzeyir için kabul ettiği “ikinci ölüm” tarihi arasına yerleştirilir.',[op('Nuh’un ölümü ile önerilen Üzeyir tarihi',[4560,346],4214)],counts=[count(2,'occurrences',4214,'Elif tekrarı',['ا'])],notes=['“İkinci ölüm” ve MÖ 346 tarihi kitabın ileride açıkladığı yorum çerçevesine aittir. Elif varyantlarının sayım kuralı ayrıca önemlidir.'],topic='noah')
add('nuh-ahkaf','Ahkāf’ın 2627 harfi ve İsmail bağlantısı',[22], 'Ahkāf suresinin 2627 harf olduğu savı, Nuh’un ölümü ile İsmail’in doğumu için seçilen tarihlerin farkıyla eşleştirilir.',[op('Nuh’un ölümü ile İsmail’in doğumu',[4560,1933],2627)],counts=[count(46,'letters',2627)],topic='noah')
add('hud-dogum','Hûd’un doğumu ve 1917 kelime',[22,23], 'Hûd suresi için verilen 1917 kelime, Hûd’un doğumu ile İbrahim’in MÖ 1844 ölümü arasındaki yıl sayısı kabul edilir; böylece MÖ 3761 doğum tarihi önerilir.',[op('İbrahim’in ölümüne önceki aralığın eklenmesi',[1844,1917],3761,'add')],counts=[count(11,'words',1917)],notes=['Sure adının kişiyi göstermesi, 1917’nin doğum mu ölüm mü ile ilişkilendirileceğini tek başına belirlemez. Yazar bunu sonraki parçalama ile gerekçelendirmeye çalışır.'],topic='hud')
add('hud-ahkaf-hac','1917’nin 643 ve 1274’e ayrılması',[23], 'Yazar 1917’den Ahkāf için verdiği 643 kelimeyi çıkarınca Hac için verdiği 1274 kelimeyi elde eder. İlk sayıyı Hûd’a, ikinci sayıyı Kâbe ve hac üzerinden İbrahim’e bağlar.',[op('Hûd–Ahkāf kelime sayılarının farkı',[1917,643],1274)],counts=[count(46,'words',643),count(22,'words',1274)],refs=[[46,21],[22,27]],topic='hud')
add('hud-kabe','Hûd’un Kâbe’yi yapmış olabileceği tarih',[23,24], 'Yazar, Hûd’un Kâbe’nin yapıcılarından biri olabileceğini ve bunu 643 yaşında yapmış olabileceğini ileri sürer. MÖ 3761’den 643 çıkarıldığında MÖ 3118 elde edilir.',[op('Önerilen doğumdan varsayılan yapım yaşının çıkarılması',[3761,643],3118)],counts=[count(46,'words',643)],refs=[[3,96]],notes=['Kaynak bu yapım iddiasını kesin değil olası olarak kurar. Burada da olasılık dili korunmuştur.','643’ün yapı yaşı kabul edilmesi ayrıca bir varsayımdır.'],topic='hud')
add('hud-1625','“İlk” sözcüğünün 1625. sırası ve Musa anlatısı',[24], 'Kitap, Âl-i İmrân 96’daki “ilk” sözcüğünün suredeki kelime sırasını 1625 olarak verir. Şuarâ’daki Musa anlatısının 1625 harf olduğunu da ileri sürerek bu sayıyı olası ilk Kâbe yapımı ile Musa’nın doğumu arasındaki yıla bağlar.',[op('Önerilen Kâbe yapımı ile Musa’nın doğumu',[3118,1493],1625)],refs=[[3,96]],notes=['Şuarâ kıssasının ayet sınırları ve sıra sayımına besmelenin dahil edilip edilmediği bu sayfada belirtilmez; varsayılarak doldurulmamıştır.'],topic='hud')
add('ad-673','Âd’ın helâki için 673 harf–yıl eşleştirmesi',[24], 'Hûd suresindeki Hûd anlatısının 673 harf olduğu kabul edilir. Bu sayı Hûd’un kavminin helâki sırasındaki yaşı sayılır ve MÖ 3088 tarihi önerilir.',[op('Önerilen doğumdan 673 yılın çıkarılması',[3761,673],3088)],notes=['Bu sayfada harfleri sayılan anlatının kesin ayet aralığı belirtilmez. Tarih ve yaş eşleştirmesi yazarın savıdır.'],topic='hud')
add('ad-hakka','Hâkka’nın 258 kelimesi ve Sâlih’in doğumu',[24], 'Hâkka suresi için verilen 258 kelime, Âd’ın helâki ile Sâlih’in MÖ 2830 doğumu arasındaki farkla eşleştirilir.',[op('Âd’ın helâki ile önerilen Sâlih doğumu',[3088,2830],258)],counts=[count(69,'words',258)],refs=[[69,1],[69,4]],topic='hud')
add('hud-olum','Hûd’un ölümü ve 123 ayet',[25], 'Yazar Hûd’un, kavminin helâkinden 123 yıl sonra öldüğünü kabul eder; bu 123 yılı Hûd suresinin ayet sayısıyla ilişkilendirir. Sonuç MÖ 2965’tir.',[op('Helâk tarihinden 123 yıl sonrası',[3088,123],2965)],counts=[count(11,'verses',123)],topic='hud')
add('hud-taha','135 ayet ve râ tekrarıyla Sâlih bağlantısı',[25], 'Tâhâ’nın 135 ayeti ve Ra‘d’daki râ harfinin 135 tekrarı, Hûd’un ölümü ile Sâlih’in doğumu arasındaki 135 yıla eşlenir.',[op('Hûd’un ölümü ile Sâlih’in doğumu',[2965,2830],135)],counts=[count(20,'verses',135),count(13,'occurrences',135,'Râ tekrarı',['ر'])],topic='hud')
add('hud-idris','137 kâf ve Fecr kelimeleriyle İdris bağlantısı',[25], 'Meryem’de kâf harfinin 137 tekrarı ve Fecr’in 137 kelimesi, Hûd’un ölümü ile İdris’in MÖ 2828 doğumu arasına yerleştirilir.',[op('Hûd’un ölümü ile İdris’in doğumu',[2965,2828],137)],counts=[count(19,'occurrences',137,'Kâf tekrarı',['ك']),count(89,'words',137)],topic='hud')
add('hud-796','Kâf–hâ–yâ–ayn–sâd toplamı: 796',[25], 'Meryem suresindeki başlangıç harflerinin tekrarları kâf 137, hâ 174, yâ 342, ayn 117 ve sâd 26 olarak verilir. Toplam 796, Hûd’un ömrüne eşit kabul edilir.',[op('Beş harfin kitapta verilen tekrar toplamı',[137,174,342,117,26],796,'add','tekrar'),op('Önerilen Hûd doğum ve ölüm farkı',[3761,2965],796)],counts=[count(19,'occurrences',137,'Kâf',['ك']),count(19,'occurrences',174,'Hâ',['ه']),count(19,'occurrences',342,'Yâ',['ي']),count(19,'occurrences',117,'Ayn',['ع']),count(19,'occurrences',26,'Sâd',['ص'])],topic='hud')
