add('hud-yunus','Yûnus’taki 1224 elif ve Efrayim’in doğumu',[26], 'Yûnus suresindeki 1224 elif tekrarı, Hûd’un ölümü ile Efrayim’in MÖ 1741 doğumu arasındaki yıl sayısına bağlanır.',[op('Hûd’un ölümü ile Efrayim’in doğumu',[2965,1741],1224)],counts=[count(10,'occurrences',1224,'Elif tekrarı',['ا'])],topic='hud')
add('ad-rum','Rûm’daki elif–lâm–mîm toplamı: 1197',[26], 'Rûm suresinde elif, lâm ve mîm tekrarlarının toplamı 1197 olarak verilir. Yazar bunu Âd’ın helâki ile Lût’un MÖ 1891 ölümü arasındaki farka bağlar.',[op('Âd’ın helâki ile Lût’un ölümü',[3088,1891],1197)],counts=[count(30,'occurrences',1197,'Elif + lâm + mîm',['ا','ل','م'])],notes=['Bu sayfa üç harfin ayrı tekrar sayılarını değil yalnızca toplamını verir.'],topic='hud')
