add('hud-hucurat','Hucurât’ın 347 kelimesi ve İdris’in yönetimi',[26,27], 'Hucurât’ın 347 kelime olduğu savı, Hûd için önerilen Kâbe yapımı ile İdris’in Mısır’da yönetime başladığı kabul edilen MÖ 2771 arasındaki yıla bağlanır.',[op('Önerilen Kâbe yapımı ile İdris’in yönetim başlangıcı',[3118,2771],347)],counts=[count(49,'words',347)],topic='hud')
